package org.telegram.messenger; import android.content.Context; import android.content.SharedPreferences; public class CustomEconomyManager { private static volatile CustomEconomyManager[] Instances = new CustomEconomyManager[UserConfig.MAX_ACCOUNT_COUNT]; private SharedPreferences preferences; public static CustomEconomyManager getInstance(int num) { CustomEconomyManager localInstance = Instances[num]; if (localInstance == null) { synchronized (CustomEconomyManager.class) { localInstance = Instances[num]; if (localInstance == null) { Instances[num] = localInstance = new CustomEconomyManager(num); } } } return localInstance; } private CustomEconomyManager(int instanceNum) { preferences = ApplicationLoader.applicationContext.getSharedPreferences("user_economy_" + instanceNum, Context.MODE_PRIVATE); } public int getCups() { return preferences.getInt("cups_balance", 0); } public void addCups(int amount) { int current = getCups(); preferences.edit().putInt("cups_balance", current + amount).apply(); NotificationCenter.getInstance(UserConfig.selectedAccount).postNotificationName(NotificationCenter.mainUserInfoChanged); } }
